Set-Location -LiteralPath $PSScriptRoot
$msg = 'sms_router: send as the LEAD-S assigned advisor, not the caller. The composer, email_router and leads_router were corrected to acting_advisor; /sms/send - the endpoint that actually puts a message on the wire - was missed, along with /sms/send-mms and /sms/send-batch. Under impersonation a send refused outright, which is loud and safe; the quiet failure is that with organization credentials present it would have resolved the ORGANIZATION shared number instead of the advisor assigned number, and a family would have been texted from a number that is not their advisor. A batch now groups leads by acting advisor and merges the counts, so one sender is never used for leads belonging to different people. Found by the Restland controlled sample test.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
